code.python:
def is_prime(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

print(29, "is prime?", is_prime(29))
print("Primes up to 30:", [x for x in range(2, 31) if is_prime(x)])

