code.python:
def is_armstrong(n):
    digits = str(n)
    k = len(digits)
    return n == sum(int(d) ** k for d in digits)

print(153, is_armstrong(153))
print("Armstrong numbers below 1000:", [x for x in range(1, 1000) if is_armstrong(x)])

