code.java:
public class Main {
    static boolean isArmstrong(int n) {
        String digits = String.valueOf(n);
        int k = digits.length(), sum = 0;
        for (char c : digits.toCharArray()) sum += (int) Math.pow(c - '0', k);
        return sum == n;
    }
    public static void main(String[] args) {
        System.out.println("153 " + (isArmstrong(153) ? "True" : "False"));
        StringBuilder sb = new StringBuilder();
        for (int x = 1; x < 1000; x++) if (isArmstrong(x)) sb.append(sb.length() > 0 ? ", " : "").append(x);
        System.out.println("Armstrong numbers below 1000: [" + sb + "]");
    }
}

