  while (b) [a, b] = [b, a % b];
  return a;
}
const a = 12, b = 18, g = gcd(a, b);
console.log("GCD:", g);
console.log("LCM:", (a * b) / g);

code.java:
public class Main {
    static int gcd(int a, int b) {
        while (b != 0) { int t = b; b = a % b; a = t; }
        return a;
    }
    public static void main(String[] args) {
        int a = 12, b = 18, g = gcd(a, b);
        System.out.println("GCD: " + g);
        System.out.println("LCM: " + a * b / g);
    }
}

