code.java:
import java.util.Arrays;

public class Main {
    static boolean isAnagram(String a, String b) {
        char[] x = a.toLowerCase().toCharArray(), y = b.toLowerCase().toCharArray();
        Arrays.sort(x);
        Arrays.sort(y);
        return Arrays.equals(x, y);
    }
    public static void main(String[] args) {
        System.out.println("listen/silent: " + (isAnagram("listen", "silent") ? "True" : "False"));
        System.out.println("hello/world: " + (isAnagram("hello", "world") ? "True" : "False"));
    }
}

code.cpp:
#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

bool isAnagram(string a, string b) {
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());
    return a == b;
}

int main() {
    cout << "listen/silent: " << (isAnagram("listen", "silent") ? "True" : "False") << endl;
    cout << "hello/world: " << (isAnagram("hello", "world") ? "True" : "False") << endl;
    return 0;
}

